          "title": "Exercise 4.5: LRU Cache Implementation using OrderedDict",
          "problem": "Build an LRUCache class with capacity using OrderedDict that implements get(key) and put(key, val) in O(1) time.",
          "starterCode": "from collections import OrderedDict\n\nclass LRUCache:\n    def __init__(self, capacity: int):\n        # Complete constructor\n        pass",
          "solution": "from collections import OrderedDict\n\nclass LRUCache:\n    def __init__(self, capacity: int):\n        self.capacity = capacity\n        self.cache = OrderedDict()\n\n    def get(self, key):\n        if key not in self.cache:\n            return -1\n        self.cache.move_to_end(key) # Mark as recently used\n        return self.cache[key]\n\n    def put(self, key, value):\n        if key in self.cache:\n            self.cache.move_to_end(key)\n        self.cache[key] = value\n        if len(self.cache) > self.capacity:\n            self.cache.popitem(last=False) # Evict oldest\n\nlru = LRUCache(2)\nlru.put(\"A\", 100)\nlru.put(\"B\", 200)\nlru.get(\"A\") # A accessed\nlru.put(\"C\", 300) # Evicts B\nprint(\"Cache keys remaining:\", list(lru.cache.keys()))",
